import sys,collections,heapq,itertools,functools,bisect
def solve(data):
    a=list(map(int,data.split()));n,m,s,t=a[:4];s-=1;t-=1;g=[[] for _ in range(n)]
    for i in range(m):
        u,v=a[4+2*i:6+2*i];u-=1;v-=1;g[u].append(v);g[v].append(u)
    d=[-1]*n;ways=[0]*n;d[s]=0;ways[s]=1;q=collections.deque([s])
    while q:
        u=q.popleft()
        for v in g[u]:
            if d[v]<0:d[v]=d[u]+1;q.append(v)
            if d[v]==d[u]+1:ways[v]=(ways[v]+ways[u])%1000000007
    return ways[t]

if __name__=="__main__":
    a=solve(sys.stdin.buffer.read().decode())
    print(" ".join(map(str,a)) if isinstance(a,(list,tuple)) else a)
